def the_lashes_and_the_muzzle(case, data):
    """F13 — Deut 25:1-4 — TWO LINES: lashes_declared (25:1-3) writing court_justification_commanded, lashes_by_number_commanded and lashes_forty_cap_declared (STATUSES) and brother_degradation_barred (a BLOCK); muzzle_declared (25:4) writing ox_muzzling_barred (a BLOCK); the strife and the muzzled beasts by CALL (primeval — Genesis 13:7), the courts by CALL (festivals_judges), the lash list and the excision's discharge by CALL (sanctions — the Leviticus cell READ 25:2-3 FORWARD), the lashing procedure by CALL (holiness_b — Makkot 3:14), the blood's a fortiori by CALL (place_name — 12:23); Makkot 3:10, 3:15 the exam rows"""
