    if ask == 'if_the_wicked_deserves_beating':
        ink('25:2', "'then if THE WICKED DESERVES BEATING (a son of beating), the judge shall make him lie down AND STRIKE HIM BEFORE HIM BY NUMBER according to his wickedness' — 'a son of beating' the floggable class; 'by number' the count's word; 25:3 shares %d token with Leviticus 19:20 (the maidservant's lashing — the restatements that share no words)" % (TWIN['25:3 vs Lev 19:20'],))
        move("the Sifrei 286:4-7 (read whole at the reading); MIDDOT.md I3 (the prototype); cold_run_sanctions (CALL) — SA.census(lashes) = %d names ('the lash itself is Deut 25:2-3's [IMPORT]'); cold_run_holiness_b (CALL) — HB.maidservant(lashing_procedure) = %s" % (len(SA_LASHES[0]), HB_LASH[0]), "'a son of beating' — THE FLOGGABLE CLASS BY THE MUZZLE'S PROTOTYPE: a prohibition like the muzzle's — an act, no death, no money — is flogged; a prohibition without an act, or with a death, or with a payment, is not (286:4 — the reading's find; I3 checked in MIDDOT.md: the prototype the muzzle of 25:4, the next verse); 'the judge shall make him lie down' — not standing, not sitting (286:5 — Makkot 3:12 by the English); 'and strike him before him' — the judge's eyes on him (286:6); THE ONE-SANCTION RULE — a death and lashes never both, a payment and lashes never both: 'according to his wickedness' — one wickedness (286:7 — the reading's find; the_one_sanction); THE LEVITICUS CELL READ THIS VERSE FORWARD — its lash list the karet-grade unions without a court death, 'the lash itself is Deut 25:2-3's [IMPORT]' (sanctions' census by CALL); the reader reads, the striker strikes, died under his hand exempt, an extra strap exile (Makkot 3:14 — holiness_b's procedure by CALL)")
        dat("THE WRITE lashes_by_number_commanded — a STATUS on israel_people at the chapters' own day (DK2); THE PARAMETER the_floggable_class (the prototype I3 — an act, no death, no money); the_one_sanction a DATA row (286:7); the_lashing_posture a DATA row (Makkot 3:12 by the English); the flogged man's own verdict lashes (the body effect reused — ZERO persons on the tape, SCANS %s); the exam's person who transgresses a prohibition without an act — not flogged, outside the prototype" % (SCANS['lashes'],))
        return out("if the wicked deserves beating (25:2) — the floggable class by the muzzle's prototype: an act, no death, no money; lying down, before the judge's eyes; one sanction, never two; the Leviticus cell read 25:2-3 forward, its lash list the class (the Sifrei 286:4-7; sanctions' %d names and holiness_b's %s by CALL; I3): THE WRITE lashes_by_number_commanded, a STATUS on Israel at the chapters' own day; the transgressor without an act not flogged" % (len(SA_LASHES[0]), HB_LASH[0][:12]), ['lashes_by_number_commanded', 'lashes'])
    if ask == 'forty_he_shall_strike_him':
        ink('25:3', "'FORTY HE SHALL STRIKE HIM, HE SHALL NOT ADD, lest he add to strike him beyond these many stripes' — the parser %s at 25:3 (the forty — the first token of the verse, %s); Onkelos 'forty he shall strike him'" % (PARSE[(25, 3)][0], W25(3)[0]))
        move("the Sifrei 286:8-12 (read whole at the reading); MISHNAH MAKKOT 3:10 (the exam row, read whole)", "FORTY AS THIRTY-NINE BY THE SEAM — 'by number' (25:2) 'forty' (25:3): a number adjacent to forty, thirty-nine (286:8 — the reading's find: the verses' seam read as one phrase); how many lashes? forty less one, 'by number forty' — a count near forty; R. Judah — forty whole, the extra one between the shoulders (Makkot 3:10 — the exam row: TWO ARMS); 'he shall not add' — the extra lash the court's own liability: the striker who added is exiled (286:9-10); 'lest he add … many stripes' — the estimate for what he can bear, in threes; estimated to bear forty and struck some and they said he cannot bear the rest — exempt (286:11-12 — the_estimate)")
